    cy.get('a#77b59e10-6723-013f-e66b-76e3324c8978').should('be.visible').click();
    // Add assertions here related to the expected outcome after clicking baz
  });

  it('should not navigate when clicking on an invalid action', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a#77b5c700-6723-013f-e66c-76e3324c8978').should('be.visible').click();
