import { test, expect } from '@playwright/test';

test.describe('Challenging DOM action buttons', () => {
  test('should successfully click the baz button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a#77b59e10-6723-013f-e66b-76e3324c8978')).toBeVisible();
    await page.locator('a#77b59e10-6723-013f-e66b-76e3324c8978').click();
    // Add assertions here related to the expected outcome after clicking baz
  });

  test('should not navigate when clicking on an invalid action', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a#77b5c700-6723-013f-e66c-76e3324c8978')).toBeVisible();
    await page.locator('a#77b5c700-6723-013f-e66c-76e3324c8978').click();
    // Assuming this button leads to an action that does not change the page
    await expect(page.url()).toBe('https://the-internet.herokuapp.com/challenging_dom');
  });
});
